"""matplotlib.table — table drawing.

The plotly backend doesn't render real tables (use ``plotly.go.Table``
directly for that), but this module tracks all the state callers set
so introspection works identically to upstream matplotlib.
"""

from matplotlib.artist import Artist
from matplotlib.text import Text


class Cell(Artist):
    """A single cell. Holds text + a backing rectangle's geometry +
    font size — all readable via the same getters upstream exposes."""

    PAD = 0.1

    def __init__(self, xy, width, height, *, edgecolor='k', facecolor='w',
                 fill=True, text='', loc='right', fontproperties=None,
                 visible_edges='closed'):
        super().__init__()
        self._xy = xy
        self._width = float(width)
        self._height = float(height)
        self._text_str = text
        self._loc = loc
        self._edgecolor = edgecolor
        self._facecolor = facecolor
        self._fill = bool(fill)
        self._fontsize = 10.0
        self._fontproperties = fontproperties
        self._visible_edges = visible_edges
        # Backing Text artist so callers that need the actual Text
        # instance (for property updates / measurement) get a real one.
        self._text_artist = Text(xy[0] + width / 2,
                                  xy[1] + height / 2,
                                  text=str(text),
                                  ha='center', va='center')

    def get_text(self):
        return self._text_artist

    def set_text_props(self, **kwargs):
        for k, v in kwargs.items():
            setter = getattr(self._text_artist, f'set_{k}', None)
            if setter is not None:
                try: setter(v)
                except Exception: pass
            if k == 'fontsize':
                self._fontsize = float(v)

    def get_path(self):
        """Rectangular path describing this cell's outline."""
        from matplotlib.path import Path
        x, y = self._xy
        w, h = self._width, self._height
        return Path([(x, y), (x + w, y), (x + w, y + h),
                      (x, y + h), (x, y)])

    def set_fontsize(self, size):
        self._fontsize = float(size)
        try: self._text_artist.set_fontsize(size)
        except Exception: pass

    def get_fontsize(self):
        return self._fontsize

    def auto_set_font_size(self, renderer):
        """Pick a font size that lets the cell text fit inside ``width``.
        Without a renderer we estimate via character count."""
        n = max(1, len(str(self._text_str)))
        # Rough: 0.6 em ≈ width/n. Convert points→inches via /72.
        est_size = max(6.0, min(self._fontsize, self._width * 72 / (0.6 * n)))
        self.set_fontsize(est_size)
        return est_size

    def get_required_width(self, renderer=None):
        """Width (in cell-fraction units) required to display the text."""
        n = len(str(self._text_str))
        # 0.6em per char at the cell's font size, in cell-fraction units.
        return max(self._width, n * self._fontsize / 72 * 0.6 + 2 * self.PAD)

    def get_text_bounds(self, renderer=None):
        """Return ``(x, y, w, h)`` of the text within the cell."""
        x, y = self._xy
        return (x + self.PAD, y + self.PAD,
                self._width - 2 * self.PAD, self._height - 2 * self.PAD)

    @property
    def visible_edges(self):
        return self._visible_edges

    @visible_edges.setter
    def visible_edges(self, v):
        self._visible_edges = v


class Table(Artist):
    """Container of :class:`Cell`'s arranged on a row/column grid."""

    codes = {'best': 0, 'upper right': 1, 'upper left': 2, 'lower left': 3,
             'lower right': 4, 'center left': 5, 'center right': 6,
             'lower center': 7, 'upper center': 8, 'center': 9}

    AXESPAD = 0.02
    FONTSIZE = 10.0

    def __init__(self, ax, loc=None, bbox=None, **kwargs):
        super().__init__()
        self.ax = ax
        self._cells = {}
        self._loc = loc
        self._bbox = bbox
        self._col_widths = {}
        self._fontsize = self.FONTSIZE
        self._auto_size_font = False
        self._scale = (1.0, 1.0)

    def add_cell(self, row, col, *args, **kwargs):
        """Insert a new cell at ``(row, col)``. Positional args are
        ``(width, height, text)`` in upstream signature."""
        # Accept upstream's (width, height, text) positional API.
        width = args[0] if len(args) >= 1 else kwargs.get('width', 1.0)
        height = args[1] if len(args) >= 2 else kwargs.get('height', 1.0)
        if 'text' not in kwargs and len(args) >= 3:
            kwargs['text'] = args[2]
        cell = Cell((0, 0), width, height,
                    **{k: v for k, v in kwargs.items()
                       if k not in ('width', 'height')})
        self._cells[(row, col)] = cell
        return cell

    def __getitem__(self, position):
        return self._cells[position]

    def __setitem__(self, position, cell):
        self._cells[position] = cell

    def __iter__(self):
        return iter(self._cells)

    def edges(self):
        """Default visible-edges for new cells."""
        return 'closed'

    def auto_set_font_size(self, value=True):
        self._auto_size_font = bool(value)
        if value:
            for c in self._cells.values():
                try: c.auto_set_font_size(None)
                except Exception: pass

    def auto_set_column_width(self, col):
        """Resize the column(s) to fit the widest cell text."""
        if hasattr(col, '__iter__') and not isinstance(col, str):
            cols = list(col)
        else:
            cols = [col]
        for ci in cols:
            widest = max(
                (c.get_required_width() for (r, c2), c in self._cells.items()
                 if c2 == ci),
                default=1.0)
            self._col_widths[ci] = widest
            for (r, c2), cell in self._cells.items():
                if c2 == ci:
                    cell._width = widest

    def scale(self, xscale, yscale):
        """Scale all cell sizes by ``(xscale, yscale)``."""
        self._scale = (float(xscale), float(yscale))
        for cell in self._cells.values():
            cell._width *= float(xscale)
            cell._height *= float(yscale)

    def set_fontsize(self, size):
        self._fontsize = float(size)
        for cell in self._cells.values():
            try: cell.set_fontsize(size)
            except Exception: pass

    def get_celld(self):
        return self._cells

    def get_children(self):
        return list(self._cells.values())


def table(ax, cellText=None, cellColours=None, cellLoc='right', colWidths=None,
          rowLabels=None, rowColours=None, rowLoc='left',
          colLabels=None, colColours=None, colLoc='center',
          loc='bottom', bbox=None, edges='closed', **kwargs):
    """Build a :class:`Table` from the supplied row/column data."""
    t = Table(ax, loc=loc, bbox=bbox)
    if cellText is None:
        return t
    rows = len(cellText)
    cols = max((len(row) for row in cellText), default=0)
    if colWidths is None:
        colWidths = [1.0 / max(cols, 1)] * cols
    row_h = 1.0 / max(rows + (1 if colLabels else 0), 1)
    # Header row (column labels).
    if colLabels is not None:
        for ci, label in enumerate(colLabels):
            fc = (colColours[ci] if colColours and ci < len(colColours) else 'w')
            t.add_cell(0, ci + (1 if rowLabels else 0),
                       colWidths[ci], row_h,
                       text=label, facecolor=fc, loc=colLoc)
    row_offset = 1 if colLabels else 0
    for ri, row in enumerate(cellText):
        # Row label
        if rowLabels is not None and ri < len(rowLabels):
            fc = (rowColours[ri] if rowColours and ri < len(rowColours) else 'w')
            t.add_cell(ri + row_offset, 0, colWidths[0], row_h,
                       text=rowLabels[ri], facecolor=fc, loc=rowLoc)
        for ci, val in enumerate(row):
            fc = ('w' if cellColours is None
                  else cellColours[ri][ci])
            t.add_cell(ri + row_offset, ci + (1 if rowLabels else 0),
                       colWidths[ci], row_h,
                       text=val, facecolor=fc, loc=cellLoc)
    return t


# ─── CustomCell — variant whose edges can be customised per side ───


class CustomCell(Cell):
    """:class:`Cell` whose visible edges can be customised individually —
    ``visible_edges`` is a string subset of ``'TBLR'`` (top/bottom/left/
    right) or one of the aliases ``'open'``, ``'closed'``, ``'horizontal'``,
    ``'vertical'``.
    """

    _edges_aliases = {
        'open':       '',
        'closed':     'TBLR',
        'horizontal': 'TB',
        'vertical':   'LR',
    }

    def __init__(self, xy, width, height, *, visible_edges='closed', **kwargs):
        super().__init__(xy=xy, width=width, height=height,
                          visible_edges=visible_edges, **kwargs)
        self.visible_edges = self._edges_aliases.get(visible_edges, visible_edges)

    def get_visible_edges(self):
        return self.visible_edges

    def set_visible_edges(self, value):
        self.visible_edges = self._edges_aliases.get(value, value)
